#include "ImageResourceLifecycleRuntime.h"
#include <cassert>
#include <cstdio>
#include <cstring>
#include <vector>
#include <iostream>
#include <memory>
static constexpr uint32_t base=0x3000000,bytes=0x200000;
struct Span{uint32_t token,size;std::unique_ptr<uint8_t[]>data;bool active;};
struct Event{uint32_t v[17];std::vector<std::pair<uint32_t,uint8_t>>before,service;std::vector<std::pair<uint32_t,bool>>live;};
struct Heap{std::vector<Span>spans;std::vector<uint32_t>image;std::vector<uint8_t>shadow;std::vector<Event>events;size_t next=0;};
uint32_t*lookup(void*u,uint32_t t,uint32_t n){auto&h=*static_cast<Heap*>(u);if(t&3)return nullptr;for(auto&s:h.spans)if(s.active&&t>=s.token&&uint64_t(t)+uint64_t(n)*4<=uint64_t(s.token)+((s.size+3)&~3u))return reinterpret_cast<uint32_t*>(s.data.get()+t-s.token);if(t>=0x400000&&uint64_t(t)+uint64_t(n)*4<=0x400000+h.image.size()*4)return h.image.data()+(t-0x400000)/4;return nullptr;}
void patch(Heap&h,uint32_t off,uint8_t v,bool native){assert(off<h.shadow.size());h.shadow[off]=v;if(!native)return;uint32_t t=off<bytes?base+off:0x510000+off-bytes;auto*p=lookup(&h,t&~3u,1);assert(p);reinterpret_cast<uint8_t*>(p)[t&3]=v;}
void live(Heap&h,uint32_t t,bool enabled){for(auto&s:h.spans)if(s.token==t){assert(s.active!=enabled);s.active=enabled;return;}assert(false);}
uint32_t dependency(ClawImageResourceLifecycleContext*,const ClawImageResourceLifecycleCall*q,void*u){auto&h=*static_cast<Heap*>(u);assert(h.next<h.events.size());auto&e=h.events[h.next++];assert(!q->localMask&&!q->bufferCount);assert(q->function==e.v[0]&&q->receiver==e.v[1]&&q->argumentCount==e.v[2]);for(uint32_t i=0;i<q->argumentCount;++i)assert(q->arguments[i]==e.v[3+i]);for(auto p:e.before)patch(h,p.first,p.second,false);for(auto&s:h.spans)if(s.active)assert(!std::memcmp(s.data.get(),h.shadow.data()+s.token-base,s.size));assert(!std::memcmp(reinterpret_cast<uint8_t*>(h.image.data())+0x110000,h.shadow.data()+bytes,0x43000));for(auto p:e.live)if(p.second)live(h,p.first,true);for(auto p:e.service)patch(h,p.first,p.second,true);for(auto p:e.live)if(!p.second)live(h,p.first,false);return e.v[13];}
void read(FILE*f,void*p,size_t n){assert(fread(p,1,n,f)==n);}uint32_t word(FILE*f){uint32_t v;read(f,&v,4);return v;}
int main(int argc,char**argv){ClawImageResourceLifecycleContext guard{};uint32_t guardOut=0x12345678;assert(!claw_image_resource_lifecycle_entry(0x12345678,0,nullptr,0,&guard,nullptr,nullptr,&guardOut)&&guardOut==0x12345678&&!guard.fault);assert(argc==2);FILE*f=fopen(argv[1],"rb");assert(f);uint32_t cases=word(f);for(uint32_t i=0;i<cases;++i){uint32_t v[17];read(f,v,sizeof(v));std::vector<uint8_t>before(bytes),after(bytes);read(f,before.data(),bytes);read(f,after.data(),bytes);Heap h;h.image.resize(0x153000/4);read(f,h.image.data(),h.image.size()*4);h.shadow=before;h.shadow.insert(h.shadow.end(),reinterpret_cast<uint8_t*>(h.image.data())+0x110000,reinterpret_cast<uint8_t*>(h.image.data())+0x153000);for(uint32_t j=0;j<v[15];++j){uint32_t t=word(f),n=word(f),active=word(f);assert(n<=bytes);Span s{t,n,std::make_unique<uint8_t[]>(n),active!=0};std::memcpy(s.data.get(),before.data()+t-base,n);h.spans.push_back(std::move(s));}for(uint32_t j=0;j<v[16];++j){Event e;read(f,e.v,sizeof(e.v));for(unsigned k=0;k<2;++k)for(uint32_t p=0;p<e.v[14+k];++p){uint32_t off=word(f);uint8_t value;read(f,&value,1);(k?e.service:e.before).emplace_back(off,value);}for(uint32_t p=0;p<e.v[16];++p){uint32_t t=word(f),active=word(f);e.live.emplace_back(t,active!=0);}h.events.push_back(std::move(e));}ClawImageResourceLifecycleContext context{};context.scene.context=&h;context.scene.lookup=lookup;uint32_t out=0;auto ok=claw_image_resource_lifecycle_entry(v[0],v[1],v+3,v[2],&context,dependency,&h,&out);if(!ok||context.fault){std::cerr<<"case "<<i<<" function "<<std::hex<<v[0]<<" fault "<<context.fault<<"\n";assert(false);}assert(!v[14]||out==v[13]);assert(h.next==h.events.size());for(auto&s:h.spans)assert(!std::memcmp(s.data.get(),after.data()+s.token-base,s.size));}assert(fgetc(f)==EOF);fclose(f);std::cout<<"PASS "<<cases<<" exact image52/surface188/compressed40/PID-input source replays with live ownership and ordered full-span snapshots\n";}
